// The service worker's offline list (sw-files.js, generated by tools/app/precache.cjs) must hold
// every file the offline pages load: the pages, their scripts, the modules those import, and the
// fonts the stylesheet names. Otherwise the installed app breaks offline although it works online.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const read = (f) => fs.readFileSync(f, 'utf8');
const PRECACHE = JSON.parse(/self\.PRECACHE = (\[[^\]]*\])/.exec(read('sw-files.js'))[1]);
const listed = new Set(PRECACHE);
const norm = (p) => path.posix.normalize(p.split(/[?#]/)[0]);
const local = (ref) => !/^([a-z]+:)?\/\//i.test(ref) && !ref.startsWith('data:') && !ref.startsWith('/');

/** Local files an HTML page pulls in: scripts, stylesheets, manifest, icons. */
function pageRefs(html) {
  const refs = [];
  for (const m of html.matchAll(/<(?:script|link)\b[^>]*?\b(?:src|href)=["']([^"']+)["']/g)) refs.push(m[1]);
  for (const m of html.matchAll(/import\(\s*['"]([^'"]+)['"]\s*\)/g)) refs.push(m[1]); // inline module scripts
  return refs.filter(local);
}

/** Relative imports of a JavaScript module (static and literal dynamic imports). */
function moduleRefs(src) {
  const refs = [];
  for (const m of src.matchAll(/(?:^|[\s;}])(?:import|export)\s*(?:[^'"();]*?\sfrom\s*)?['"]([^'"]+)['"]/gm)) refs.push(m[1]);
  for (const m of src.matchAll(/\bimport\(\s*['"]([^'"]+)['"]\s*\)/g)) refs.push(m[1]);
  return refs.filter((r) => r.startsWith('.'));
}

/** Everything an entry page needs, found by following its references. Returns { files, broken }. */
function closure(page) {
  const files = new Set([page]), broken = [];
  const visit = (from, ref) => {
    const file = norm(path.posix.join(path.posix.dirname(from), ref));
    if (files.has(file)) return;
    if (!fs.existsSync(file)) { broken.push(`${from} → ${ref}`); return; }
    files.add(file);
    const text = read(file);
    if (file.endsWith('.js')) for (const r of moduleRefs(text)) visit(file, r);
    else if (file.endsWith('.css')) for (const m of text.matchAll(/url\(\s*['"]?([^'")]+)['"]?\s*\)/g)) if (local(m[1])) visit(file, m[1]);
  };
  for (const r of pageRefs(read(page))) visit(page, r);
  return { files, broken };
}

test('precache: sw-files.js lists exactly what tools/app/precache.cjs generates', () => {
  const out = execFileSync(process.execPath, ['tools/app/precache.cjs', '--check'], { encoding: 'utf8' });
  assert.match(out, /up to date/);
});

test('precache: every listed file exists, once, with a relative path', () => {
  assert.equal(listed.size, PRECACHE.length, 'duplicate entries');
  assert.ok(listed.has('./'), 'the start URL "./" must be cached');
  for (const f of PRECACHE) {
    if (f === './') continue;
    assert.ok(!f.startsWith('/') && !f.includes('\\'), `${f}: use relative paths with forward slashes`);
    assert.ok(fs.existsSync(f), `${f} is listed but missing on disk`);
  }
});

test('precache: the service worker caches the shared names it expects', () => {
  const sw = read('sw.js');
  assert.match(sw, /importScripts\(['"]sw-files\.js['"]\)/);
  assert.match(sw, /PRECACHE\.map/);
});

for (const page of ['index.html', 'test.html', 'welt.html']) {
  test(`precache: ${page} works offline (its scripts, modules, styles and fonts are listed)`, () => {
    const { files, broken } = closure(page);
    assert.deepEqual(broken, [], `imports that do not resolve to a file:\n${broken.join('\n')}`);
    const missing = [...files].filter((f) => !listed.has(f));
    assert.deepEqual(missing, [], `not in sw-files.js (add to tools/app/precache.cjs and regenerate):\n${missing.join('\n')}`);
  });
}

// Known gap, tracked rather than hidden: the world view is online-only today (CesiumJS from the CDN,
// the LGLN aerial service), so welt.html, its data and its art are not precached. The test lists what
// an offline world view would still need; it stays a TODO until that is decided.
test('precache: welt.html and its local data (decision pending: online-only for now)', { todo: 'welt.html needs the network anyway; decide whether the data should be precached' }, () => {
  const { files, broken } = closure('welt.html');
  assert.deepEqual(broken, []);
  const data = ['assets/manifest.json', 'assets/welt/boni_umgebung.jpg', 'assets/welt/boni_umgebung.json', 'assets/intro/boni_platz.glb', 'assets/intro/boni_schatten_hoehen.png',
    ...fs.readdirSync('locations/boni/geo').filter((f) => f.endsWith('.geojson') || f === 'rahmen.json').map((f) => `locations/boni/geo/${f}`)];
  const missing = [...files, ...data].filter((f) => !listed.has(f));
  assert.deepEqual(missing, [], `not precached:\n${missing.join('\n')}`);
});
